	Member, Parent string
	RawSame, MergedSame, SameReference, DistinctRejected, WarmStable bool
}

func (c *Checker) QualifyArrayParents(node *ast.Node) []ArrayParentControl {
	t := c.checkExpression(node)
	types := []*Type{t}
	if t.flags&TypeFlagsUnion != 0 { types=t.Types() }
	rows:=[]ArrayParentControl{}
	for _,part:=range types {
		if part.symbol == nil || part.symbol.Parent == nil { panic("missing member parent") }
		parent:=part.symbol.Parent
		merged:=c.getMergedSymbol(parent)
		global:=c.globalArrayType.symbol
		if c.isReadonlyArraySymbol(parent) { global=c.globalReadonlyArrayType.symbol }
		copy:=c.newSymbol(parent.Flags,parent.Name)
		copy.Declarations=parent.Declarations
		row:=ArrayParentControl{Member:part.symbol.Name,Parent:parent.Name,RawSame:parent==global,MergedSame:merged==global,SameReference:c.getSymbolIfSameReference(parent,global)!=nil,DistinctRejected:c.getSymbolIfSameReference(copy,global)==nil,WarmStable:true}
		for i:=0;i<3;i++ { row.WarmStable = row.WarmStable && c.getMergedSymbol(parent)==merged && c.getSymbolIfSameReference(parent,global)!=nil }
		rows=append(rows,row)
	}
	return rows
}

func (c *Checker) QualifyClonePublication() bool {
 source:=c.newSymbol(ast.SymbolFlagsInterface,"Array")
 target:=c.cloneSymbol(source)
 return source!=target && c.getMergedSymbol(source)==target && c.getMergedSymbol(target)==target && c.getSymbolIfSameReference(source,target)==source
}

