package checker

import "github.com/microsoft/typescript-go/internal/ast"

type ModuleCallControl struct {
	Name string
	TailShared, LinkedShared, TailError, LinkedError bool
	CallsAny, CallsError map[string]bool
	WarmStable bool
}

func (c *Checker) QualifyModuleCalls(head, tail, linked *ast.Symbol, calls map[string]*ast.Node, reverse bool) ModuleCallControl {
	if reverse { c.getTypeOfSymbol(head) } else { c.getTypeOfSymbol(tail) }
	h := c.getTypeOfSymbol(head)
	t := c.getTypeOfSymbol(tail)
	l := c.getTypeOfSymbol(linked)
	row := ModuleCallControl{TailShared:t==h,LinkedShared:l==h,TailError:t==c.errorType,LinkedError:l==c.errorType,CallsAny:map[string]bool{},CallsError:map[string]bool{},WarmStable:true}
	for _,name := range []string{"Head(1)","Tail(3)","Linked(4)"} {
		value := c.checkExpression(calls[name])
		row.CallsAny[name] = value == c.anyType
		row.CallsError[name] = value == c.errorType
		for i:=0;i<3;i++ { row.WarmStable = row.WarmStable && c.checkExpression(calls[name]) == value }
	}
	row.WarmStable = row.WarmStable && c.getTypeOfSymbol(tail)==t && c.getTypeOfSymbol(linked)==l && c.getTypeOfSymbol(head)==h
	return row
}

