package checker_test

import (
    "slices"
    "testing"
    "github.com/microsoft/typescript-go/internal/bundled"
    "github.com/microsoft/typescript-go/internal/compiler"
    "github.com/microsoft/typescript-go/internal/core"
    "github.com/microsoft/typescript-go/internal/tsoptions"
    "github.com/microsoft/typescript-go/internal/vfs/vfstest"
)

func TestTSRAliasDiagnosticPreservation(t *testing.T) {
    cases := []struct{name string; files map[string]string; expected []int32}{
        {"namespace-chain", map[string]string{"/main.ts":"namespace M { namespace N { class C {} } import R = N; export import X = R; }"}, nil},
        {"external-chain", map[string]string{"/a.ts":"export namespace m { export function foo() {} }", "/main.ts":"import x = require('./a'); import y = x; y.m.foo();"}, nil},
        {"default-type-only", map[string]string{"/a.ts":"export class A {}", "/b.ts":"import type * as types from './a'; export default types;", "/main.ts":"import types from './b'; new types.A();"}, []int32{1361}},
        {"namespace-type-only", map[string]string{"/a.ts":"export class A {}", "/b.ts":"import type * as types from './a'; export = types;", "/main.ts":"import * as types from './b'; new types.A();"}, []int32{1361}},
        {"mixed-type-only", map[string]string{"/a.ts":"const A = {}; export { A };", "/b.ts":"import { A } from './a'; type A = any; export type { A };", "/c.ts":"import { A } from './b'; namespace A {} export { A };", "/main.ts":"import { A } from './c'; A;"}, []int32{1362}},
    }
    for _,tc:=range cases {
        tc.files["/tsconfig.json"]=`{"compilerOptions":{"module":"commonjs","target":"es2015","esModuleInterop":true,"noLib":true},"files":["main.ts"]}`
        fs:=bundled.WrapFS(vfstest.FromMap(tc.files,false))
        host:=compiler.NewCompilerHost("/",fs,bundled.LibPath(),nil,nil)
        config,errors:=tsoptions.GetParsedCommandLineOfConfigFile("/tsconfig.json",&core.CompilerOptions{},nil,host,nil)
        if len(errors)!=0 {t.Fatal(errors)}
        p:=compiler.NewProgram(compiler.ProgramOptions{Config:config,Host:host})
        p.BindSourceFiles()
        for warm:=0;warm<2;warm++ {
            var codes []int32
            for _,d:=range p.GetSemanticDiagnostics(t.Context(),p.GetSourceFile("/main.ts")) {codes=append(codes,d.Code())}
            t.Logf("case=%s warm=%d codes=%v",tc.name,warm,codes)
            if !slices.Equal(codes,tc.expected) {t.Errorf("%s: got %v want %v",tc.name,codes,tc.expected)}
        }
    }
}

