type DefaultChainControl struct {TargetName,ImmediateName string; TargetOriginal,TargetImmediate,TargetResolvedImmediate,Unknown,Error,WarmStable bool}
func (c *Checker) QualifyDefaultChain(alias, immediate, original *ast.Symbol) DefaultChainControl {
 target:=c.resolveAlias(alias);value:=c.getTypeOfSymbol(alias)
 row:=DefaultChainControl{TargetName:target.Name,ImmediateName:immediate.Name,TargetOriginal:target==original,TargetImmediate:target==immediate,TargetResolvedImmediate:target==c.resolveSymbol(immediate),Unknown:target==c.unknownSymbol,Error:value==c.errorType,WarmStable:true}
 for i:=0;i<3;i++ {row.WarmStable=row.WarmStable && target==c.resolveAlias(alias) && value==c.getTypeOfSymbol(alias)}
 return row
}

