package checker

import "github.com/microsoft/typescript-go/internal/ast"

type MergedCallableControl struct { Calls, Constructs int; Returns []string; WarmStable bool }

func (c *Checker) QualifyMergedCallable(symbol *ast.Symbol) MergedCallableControl {
    ty:=c.getTypeOfSymbol(symbol)
    calls:=c.getSignaturesOfType(ty,SignatureKindCall)
    constructs:=c.getSignaturesOfType(ty,SignatureKindConstruct)
    row:=MergedCallableControl{Calls:len(calls),Constructs:len(constructs),WarmStable:true}
    for _,s:=range calls {row.Returns=append(row.Returns,c.TypeToString(c.getReturnTypeOfSignature(s)))}
    for i:=0;i<3;i++ {row.WarmStable=row.WarmStable && c.getTypeOfSymbol(symbol)==ty && len(c.getSignaturesOfType(ty,SignatureKindCall))==len(calls) && len(c.getSignaturesOfType(ty,SignatureKindConstruct))==len(constructs)}
    return row
}

