package checker_test

import (
	"encoding/json"
	"fmt"
	"strings"
	"testing"
	"github.com/microsoft/typescript-go/internal/ast"
	"github.com/microsoft/typescript-go/internal/bundled"
	"github.com/microsoft/typescript-go/internal/compiler"
	"github.com/microsoft/typescript-go/internal/core"
	"github.com/microsoft/typescript-go/internal/tsoptions"
	"github.com/microsoft/typescript-go/internal/vfs/vfstest"
)

func TestTSRModuleCallAliases(t *testing.T) {
	libraries:=[]string{
		"function Foo(n: number): string { return 'body'; } export = Foo;",
		"function Foo(n: number): string { return 'body'; } namespace Foo { export const own = 7; } export = Foo;",
		"class Foo { static own = 7; instance = 'instance'; } export = Foo;",
		"class Foo { static own = 7; instance = 'instance'; } namespace Foo { export const right = 'right'; } export = Foo;",
		"namespace Foo { export const own = 7; } export = Foo;",
	}
	for library,lib:=range libraries { for _,strict:=range []bool{false,true} { for _,reverse:=range []bool{false,true} {
		use:="import * as Head from './lib'; import * as Twin from './lib'; import Raw = require('./lib'); import Tail = Linked; import Linked = Head; Head(1); Twin(2); Tail(3); Linked(4); Raw(5); Head.default(6); new Head(7); new Raw(8); new Head.default(9);"
		fs:=bundled.WrapFS(vfstest.FromMap(map[string]string{
			"/global.d.ts":"interface Function {}",
			"/lib.ts":lib,
			"/use.ts":use,
			"/tsconfig.json":fmt.Sprintf(`{"compilerOptions":{"module":"commonjs","esModuleInterop":true,"noLib":true,"strictNullChecks":%v,"noEmit":true},"files":["global.d.ts","lib.ts","use.ts"]}`,strict),
		},false))
		host:=compiler.NewCompilerHost("/",fs,bundled.LibPath(),nil,nil)
		config,errors:=tsoptions.GetParsedCommandLineOfConfigFile("/tsconfig.json",&core.CompilerOptions{},nil,host,nil)
		if len(errors)!=0 {t.Fatal(errors)}
		p:=compiler.NewProgram(compiler.ProgramOptions{Config:config,Host:host});p.BindSourceFiles();c,done:=p.GetTypeChecker(t.Context())
		syms:=map[string]*ast.Symbol{};calls:=map[string]*ast.Node{}
		var visit func(*ast.Node)bool
		visit=func(n *ast.Node)bool {
			if n.Kind==ast.KindIdentifier { name:=n.Text();switch name {case "Head","Tail","Linked":if syms[name]==nil {syms[name]=c.GetSymbolAtLocation(n)}} }
			if n.Kind==ast.KindCallExpression {calls[strings.TrimSpace(use[n.Pos():n.End()])]=n}
			n.ForEachChild(visit);return false
		}
		p.GetSourceFile("/use.ts").ForEachChild(visit)
		for _,name:=range []string{"Head","Tail","Linked"} {if syms[name]==nil {t.Fatal(name)}}
		for _,name:=range []string{"Head(1)","Tail(3)","Linked(4)"} {if calls[name]==nil {t.Fatal(name,calls)}}
		row:=c.QualifyModuleCalls(syms["Head"],syms["Tail"],syms["Linked"],calls,reverse)
		data,_:=json.Marshal(row);t.Logf("library=%d strict=%v reverse=%v %s",library,strict,reverse,data)
		if !row.WarmStable {t.Error("unstable warm results")}
		done()
	}}}
}

