package checker

import "github.com/microsoft/typescript-go/internal/ast"

type SelectedConsumerControl struct {
 AliasOriginal, AliasImmediate, CopiesDistinct, PrototypeSymbolShared, PrototypeParentShared, PrototypeTypeShared, WarmStable, TailShared, TailError bool
 TargetName string
}

func (c *Checker) QualifySelectedConsumers(head, twin, raw, react, original, tail *ast.Symbol, reverse bool) SelectedConsumerControl {
 if reverse { c.getTypeOfSymbol(tail) }
 h := c.getTypeOfSymbol(head)
 t := c.getTypeOfSymbol(twin)
 r := c.getTypeOfSymbol(raw)
 hp := c.getPropertyOfType(h, "prototype")
 tp := c.getPropertyOfType(t, "prototype")
 rp := c.getPropertyOfType(r, "prototype")
 target := c.resolveAlias(react)
 module := c.resolveExternalModuleName(c.getDeclarationOfAliasSymbol(react), c.getModuleSpecifierForImportOrExport(c.getDeclarationOfAliasSymbol(react)), true)
 immediate := c.getTargetOfModuleDefault(module, c.getDeclarationOfAliasSymbol(react), true)
 row := SelectedConsumerControl{AliasOriginal: target == original, AliasImmediate: target == immediate, TargetName: target.Name, CopiesDistinct: h != r && h != t && t != r, PrototypeSymbolShared: hp == rp && tp == rp, PrototypeParentShared: c.getParentOfSymbol(hp) == c.getParentOfSymbol(rp), PrototypeTypeShared: c.getTypeOfSymbol(hp) == c.getTypeOfSymbol(rp) && c.getTypeOfSymbol(tp) == c.getTypeOfSymbol(rp), WarmStable: true, TailShared: c.getTypeOfSymbol(tail) == h, TailError: c.getTypeOfSymbol(tail) == c.errorType}
 for i:=0;i<3;i++ { row.WarmStable = row.WarmStable && c.resolveAlias(react) == target && c.getTypeOfPropertyOfType(h,"prototype") == c.getTypeOfPropertyOfType(r,"prototype") }
 return row
}

