#[test]
fn namespace_import_values_retain_distinct_module_symbol_owners() {
    for checked_first in [false, true] {
        let arena = Arena::new();
        let fixture = program(
            &arena,
            &[
                (
                    "lib",
                    "class Foo { static field = 11; } namespace Foo { export const merged = 1; } export = Foo;",
                ),
                (
                    "main",
                    "import * as Head from './lib'; import * as Twin from './lib'; import Raw = require('./lib');",
                ),
            ],
        );
        let root = fixture.host.files[1].1;
        let locals = fixture.bound.locals(root).unwrap();
        let mut checker = Checker::with_module_host(
            &fixture.bound,
            &fixture.nodes,
            &fixture.node_map,
            Some(&fixture.host),
        );
        checker.apply_compiler_options(&tsr_core::CompilerOptions {
            module: tsr_core::ModuleKind::CommonJS,
            ..Default::default()
        });
        if checked_first {
            checker.check_source_file(
                root,
                tsr_checker::check::FileContext { ambient: false, has_parse_errors: false },
            );
        }
        let head = checker.get_type_of_symbol(locals["Head"]);
        let twin = checker.get_type_of_symbol(locals["Twin"]);
        let raw = checker.get_type_of_symbol(locals["Raw"]);
        let owner = |ty| match &checker.type_of(ty).data {
            tsr_checker::TypeData::Anonymous { symbol, .. } => symbol.clone(),
            other => panic!("expected anonymous module value, got {other:?}"),
        };
        assert_ne!(owner(head), owner(raw), "a module copy must own its anonymous value");
        assert_ne!(owner(head), owner(twin), "separate imports need separate cloned symbols");
        assert_eq!(head, checker.get_type_of_symbol(locals["Head"]));
        assert_eq!(twin, checker.get_type_of_symbol(locals["Twin"]));
    }
}

/// Pinned5b ExpressionIsAlias/getTargetOfAliasLikeExpression; the full
/// exportDefaultQualifiedNameNoError corpus path must retain the property owner.
#[test]
fn property_valued_default_exports_resolve_their_selected_alias_target() {
    for (library, expected, property) in [
        ("class C { static value = 7; } export default C.value;", "number", true),
        (
            "namespace N { export namespace M { export const value = 7; } } export default N.M.value;",
            "7",
            false,
        ),
        ("const N = { M: { value:7 } }; export default N.M.value;", "number", true),
    ] {
        let arena = Arena::new();
        let fixture = program(
            &arena,
            &[
                ("m", library),
                ("main", "import Default from './m'; export const result = Default;"),
            ],
        );
        let root = fixture.host.files[1].1;
        let alias = fixture.bound.lookup_local(root, "Default").unwrap();
        for check_first in [false, true] {
            let mut checker = Checker::with_module_host(
                &fixture.bound,
                &fixture.nodes,
                &fixture.node_map,
                Some(&fixture.host),
            );
            checker.apply_compiler_options(&tsr_core::CompilerOptions {
                module: tsr_core::ModuleKind::CommonJS,
                ..Default::default()
            });
            if check_first {
                for &(_, file) in &fixture.host.files {
                    checker.check_source_file(
                        file,
                        tsr_checker::check::FileContext { ambient: false, has_parse_errors: false },
                    );
                }
            }
            for _ in 0..3 {
                let target = checker.resolve_alias(alias).expect("native selected property target");
                let view = checker.symbol_access().view(&target).unwrap();
                assert_eq!(view.name(), "value");
                assert_eq!(view.flags().intersects(SymbolFlags::PROPERTY), property);
                let ty = checker.get_type_of_symbol(alias);
                assert_eq!(checker.type_to_string(ty), expected);
            }
            assert!(checker.diagnostics().is_empty());
        }
    }
}

